package com.primehr.learningdevelopment;
import com.primehr.learningdevelopment.domain.LdEvaluationLevel;import com.primehr.learningdevelopment.evaluation.domain.*;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.time.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class LdEvaluationDomainTest {
 @Test void tasksFreezeInstrumentRulesAndCannotBeSatisfiedTwice(){LdEvaluationLevel level=level(LdEvaluationLevel.Type.BEHAVIOR_APPLICATION,30,LdEvaluationLevel.ScoreMethod.PERCENTAGE,new BigDecimal("75"));LdEvaluationTask task=new LdEvaluationTask("A","C","O","EMP","F","fingerprint",level,LdEvaluationTask.EvaluatorRole.SUPERVISOR,"SUP",LocalDate.of(2026,1,1));assertThat(task.getDueDate()).isEqualTo(LocalDate.of(2026,1,31));assertThat(task.getPassingScore()).isEqualByComparingTo("75");task.satisfy("RESULT");assertThatThrownBy(()->task.satisfy("OTHER")).isInstanceOf(IllegalStateException.class);task.reopen();assertThat(task.getStatus()).isEqualTo(LdEvaluationTask.Status.OPEN);}
 @Test void resultDecisionRequiresIndependentVerifierAndPreservesRevision(){LdEvaluationResult result=new LdEvaluationResult("A","TASK",2,"PRIOR",new BigDecimal("88"),true,"Observed application","EVIDENCE-1","SUP",Instant.parse("2026-02-01T00:00:00Z"),"fingerprint");assertThatThrownBy(()->result.decide(true,"Verified","SUP",Instant.now())).isInstanceOf(IllegalArgumentException.class);result.decide(true,"Verified evidence","LD-ADMIN",Instant.now());assertThat(result.getStatus()).isEqualTo(LdEvaluationResult.Status.VERIFIED);assertThat(result.getResultRevision()).isEqualTo(2);}
 @Test void learningActionPlanSeparatesSubmissionFromDelayedSupervisorFollowThrough(){LdLearningActionPlan plan=new LdLearningActionPlan("A","C","EMP","SUP","Apply skill","Reduce cycle time",LocalDate.of(2026,3,1));plan.submit("EMP",Instant.now());assertThatThrownBy(()->plan.followUp(true,"Done",null,"Verified","EMP",Instant.now())).isInstanceOf(IllegalArgumentException.class);plan.followUp(true,"Applied in production","DOC-1","Verified","SUP",Instant.now());assertThat(plan.getStatus()).isEqualTo(LdLearningActionPlan.Status.VERIFIED);}
 private LdEvaluationLevel level(LdEvaluationLevel.Type type,int days,LdEvaluationLevel.ScoreMethod method,BigDecimal passing){LdEvaluationLevel value=mock(LdEvaluationLevel.class);when(value.getLevelType()).thenReturn(type);when(value.isRequired()).thenReturn(true);when(value.getDueAfterDays()).thenReturn(days);when(value.getScoreMethod()).thenReturn(method);when(value.getPassingScore()).thenReturn(passing);when(value.getEvidenceRequirements()).thenReturn("Supervisor evidence");when(value.getInstrumentGuidance()).thenReturn("Use approved instrument");return value;}
}
